def sequential_search(dlist, item):
    """Write a function to search an element in the given array by using sequential search.

    Search ``dlist`` sequentially from the first element onwards.

    Returns:
        (True, index): if ``item`` is found, with the index of its
            first occurrence.
        (False, -1): if ``item`` is not present in ``dlist``.
    """
    for pos, value in enumerate(dlist):
        if value == item:
            return True, pos
    return False, -1
